def choose_timeout(supplied):
    return 30 if supplied is None else supplied

def active_name(user):
    return user is not None and user.get("active") and user.get("name")

print(choose_timeout(None)) # 30: missing value
print(choose_timeout(0))    # 0: valid explicit value
print(active_name(None))    # False; no dictionary access
print(active_name({"active": True, "name": "Ada"})) # Ada
```

